"""Build a standalone Dutch slide deck using only the repository corpus."""
from pathlib import Path
import csv, html
ROOT=Path(__file__).resolve().parents[1]
esc=html.escape
sources={}
for fn,label,url in [('standards-matrix.csv','standaard','primaire_bron'),('literature-matrix.csv','titel','doi_of_stabiele_bron')]:
    with (ROOT/fn).open(encoding='utf-8-sig') as f:
        for r in csv.DictReader(f): sources[r['id']]=(r[label],r[url],r.get('bewijsniveau',''),r.get('versie',r.get('jaar','')))
slides=[]
def cards(items):
    return '<div class="cards">'+''.join(f'<article><h3>{a}</h3><p>{b}</p></article>' for a,b in items)+'</div>'
def table(head,rows):
    return '<div class="table-wrap"><table><thead><tr>'+''.join(f'<th>{h}</th>' for h in head)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{x}</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def add(tag,title,body,refs='',note='',kind=''):
    foot=' · '.join(f'<a href="#source-{s}">{s}</a>' for s in refs.split())
    slides.append(f'<section class="slide {kind}" aria-label="Dia {len(slides)+1}: {esc(title)}"><div class="eyebrow">{tag}</div><h2>{title}</h2><div class="content">{body}</div><footer>{foot or "Ontwerpsynthese · geen empirisch resultaat"}</footer><aside class="notes"><strong>Sprekersnotitie</strong><p>{note}</p></aside></section>')
add('Onderzoek × productontwikkeling','Semantic Master<br>Data Product', '<p class="lead">Betekenis, bron en historie als expliciet onderdeel van masterdata.</p><div class="title-line">Nederlandse overheid · Stelsel van Basisregistraties</div><div class="stamp">Bijlage bij het MDM-prototype · pre-evaluation research state</div>',note='Deze presentatie vertaalt de herziene paper naar een overdraagbaar verhaal voor productteam, architecten en onderzoekers. Het prototype bestaat, maar is niet formeel geëvalueerd. De presentatie beschrijft geen geverifieerde productfunctionaliteit.',kind='cover')
add('01 / Leeswijzer','Zes soorten uitspraken.<br>Eén duidelijke bewijsgrens.',cards([('Literatuur & standaarden','Bestaande kennis en specificaties, met bronbeperkingen.'),('Requirements & principes','Afgeleide ontwerpkeuzen; nog te toetsen.'),('Reference architecture','Voorgestelde verantwoordelijkheden en verbindingen.'),('Bestaand prototype','Onderzoeksartefact; implementatie nog te inventariseren.'),('Evaluatie','Gepland protocol, zonder gemeten uitkomsten.'),('Centrale these','Falsifieerbare verwachting van praktische nettowaarde.')]),note='De architectuur is niet uit het prototype gelegitimeerd. Aanwezigheid van een bron of standaard is geen bewijs van conformiteit of effectiviteit.')
add('02 / Probleem','Een veldnaam vertelt<br>niet het hele verhaal.','<p class="lead">Een schema kan structuur vastleggen. Voor interpretatie moeten ook referent, betekenis en context worden vastgesteld.</p>'+cards([('Betekenis','Bedoelen twee gelijknamige velden hetzelfde concept?'),('Identiteit & tijd','Hetzelfde object, hetzelfde record of dezelfde versie? Geldig wanneer, bekend wanneer?'),('Gezag','Wie ondersteunt deze specifieke uitspraak en op welke grond?')]),'S08 S11 S31 L14 S25',note='Dit is de probleemanalyse uit het corpus, geen vastgestelde fout in een basisregistratie. Dezelfde term kan contextafhankelijk verschillende begrippen aanduiden; een definitie is geen datastructuur.')
add('03 / Werkdefinitie','Wat noemen we hier een SMDP?','<p class="lead">Een beheerd dataproduct dat herbruikbare uitspraken over geïdentificeerde entiteiten expliciet verbindt met hun interpretatiecontext.</p>'+cards([('Inhoud','Masterdata-uitspraken en getypeerde verwijzingen naar betekenis, bron en tijd.'),('Verantwoordelijkheid','Een eigenaar, doel, versie en expliciete beheerbesluiten.'),('Contract','Afspraken om context, gezagsgrond en ontbrekend bewijs te verkrijgen.')])+'<p class="callout">Werkdefinitie van de paper. Geen nieuwe officiële standaard of bewezen productcategorie.</p>','L05 L12 L18 S08 S33 S51',note='De definitie is een ontwerpsynthese. Een conventionele implementatie kan hieraan voldoen. Het experiment vergelijkt eigenschappen, niet het etiket SMDP.')
add('04 / Begripsgrenzen','Verbind rollen.<br>Maak ze niet stilzwijgend gelijk.',table(['Rol','Betekenis in het voorstel'],[['Term / definitie / concept','Aanduiding / betekenisomschrijving / bedoelde begripselement.'],['Klasse / objecttype / data-element','Ontologische formalisering / informatiemodelconstructie / betekenis met representatie.'],['Entiteit / record / identifier','Bedoelde referent / geregistreerde beschrijving / identificerend teken binnen een scope.'],['Masterdata / referentiedata','Herbruikbare entiteitsgegevens / gedeelde waardenstelsels voor verwijzing of classificatie.'],['Dataset / dienst / product','Gegevensverzameling / toegangsdienst / beheerde combinatie met doel en contract.']]),'S08 S13 S31 S47 L05 L12',note='Dit zijn beknopte werkonderscheidingen; zie de paper voor volledige definities. Rollen onderscheiden betekent niet dat alle resources universeel disjunct moeten zijn. Mappings en meervoudige rollen vragen expliciet profielbeleid.')
add('05 / Bijdrage & hypothese','De meerwaarde zit mogelijk<br>in de verbindingen.','<p class="lead">Voorgestelde hypothese: expliciete contextbinding verbetert correcte én herleidbare interpretatie, binnen aanvaardbare fout- en kostengrenzen.</p>'+cards([('Bestaand werk','Semantisch MDM en masterdatakwaliteitsmodellen bestaan al. Nieuwheid kan daarop niet worden geclaimd.'),('Kandidaatbijdrage','Context per uitspraak, expliciete modelgrenzen en een toetsbare koppeling van requirements aan ontwerp.'),('Open vraag','Levert dit meer op dan dezelfde informatie in een eenvoudiger contextregister?')]),'L18 L19 L13',note='De research gap blijft begrensd en voorlopig. Een standaardeninventaris alleen is geen voldoende wetenschappelijke bijdrage. Nettowaarde en noodzakelijkheid zijn nog onbewezen.')
add('06 / Design Science Research','Van bron naar ontwerp.<br>Van ontwerp naar toets.','<div class="flow"><div>Bronanalyse</div><b>→</b><div>Requirements</div><b>→</b><div>Ontwerp</div><b>→</b><div>Evaluatie</div></div>'+cards([('Nu beschikbaar','Paper, bronregisters, 23 requirements, 9 kandidaatprincipes en reference architecture.'),('Volgende formatieve fase','Onafhankelijke review, casusdossier en concrete prototype-inventarisatie.'),('Daarna summatief','Bevroren artefactversie, vooraf vastgelegde criteria en onafhankelijke beoordeling.')]),'L01 L02 L03',note='Dit is een pre-evaluation DSR-bijdrage. De bestaande documentaudit controleert verwijzingen, niet de effectiviteit van het prototype.')
add('07 / Integratie','Standaarden verdelen het werk.',table(['Probleem & niveau','Bouwstenen uit het corpus','Grens / noodzakelijke verbinding'],[['Terminologie & begrippen','ISO 704 · NL-SBB · SKOS','Definities en begripsrelaties specificeren geen volledig recordschema.'],['Modellen & representatie','MIM · ISO/IEC 11179 · ISO 8000','Betekenis en representatie koppelen; volledige normconformiteit vraagt toepasselijke normteksten.'],['Formalisering & toetsing','RDF/RDFS · OWL · SHACL','Representatie, inferentie en validatie onderscheiden; geen bewijs van feitelijke juistheid.'],['Herkomst & kwaliteit & tijd','PROV-O · DQV · OWL-Time','Herkomst is geen gezagsbewijs; tijdvocabulaire bepaalt niet vanzelf registratiehistorie.'],['Publicatie & distributie','DCAT-AP-NL · OpenAPI · REST-regels','Catalogus en interface lossen domeinbetekenis niet zelfstandig op.']]),'S11 S14 S31 S13 S08 S03 S28 S29 S30 S32 S33 S34 S37 S16 S19 S18',note='De tabel is een cross-standard synthese, geen verplicht implementatiepakket. Specificaties, vocabularia, metamodellen en normen hebben verschillende rollen. Versies en bewijsbeperkingen staan in de ingesloten bronnenindex.')
add('08 / Context & proportionaliteit','Niet iedere bouwsteen<br>is voor iedere toepassing nodig.',cards([('Organisatie & juridisch kader','EIF, Interoperable Europe Act en BOMOS geven context voor interoperabiliteit en beheer; geen compleet semantisch productschema.'),('Domein & hergebruik','NEN 3610 en SEMIC waar toepasselijk; FAIR als richting voor vindbaarheid en hergebruik, niet als effectbewijs.'),('Transport & wijzigingen','Digikoppeling/FSC en NL GOV CloudEvents bij passende uitwisselings- of notificatievereisten.'),('Ontologische verdieping','UFO/OntoUML alleen bij gemotiveerde identiteit- of rolvragen en aanvaardbare kosten.')]),'S43 S42 S23 S17 S44 L11 S20 S21 S22 S40 S41',note='OntoUML is geen Nederlandse overheidsstandaard. De presentatie doet geen nieuwe uitspraak over actuele wettelijke verplichtingen of lijststatus; daarvoor geldt de bron- en versiecontrole in het dossier.')
add('09 / Reference architecture','Vijftien views.<br>Geen vijftien verplichte systemen.','<div class="architecture"><div class="stack"><div><small>C1–C3</small><strong>Gezag → terminologie → begrippen</strong></div><div><small>C4–C6</small><strong>Ontologie* ↔ informatiemodellen ↔ data-elementen</strong></div><div><small>C10–C11</small><strong>Constraints & kwaliteit ↔ master- en referentiedata</strong></div><div><small>C12</small><strong>Productmanifest & catalogus</strong></div><div><small>C13–C15</small><strong>Distributie ↔ events* → applicatie / AI*</strong></div></div><div class="rail">C7 Identiteit<br><br>C8 Tijd<br><br>C9 Provenance<br><hr>Governance<br>Lifecycle<br>Versiebeheer</div></div><p class="caption">Pijlen: voorgestelde informatieafhankelijkheden. * Conditioneel. Fysieke centralisatie is geen eis.</p>',note='Alle vijftien componenten uit de paper zijn getoond. Deze figuur beschrijft het voorstel en mag niet worden gepresenteerd als bestaande implementatiearchitectuur.')
add('10 / Formeel ontwerp','Bind context aan de uitspraak.','<div class="formula">Bewering = inhoud + eigen identiteit + context</div><div class="flow compact"><div>Onderwerp</div><b>→</b><div>Relatie</div><b>→</b><div>Object / waarde</div></div>'+cards([('Eigen contextrecord','Bronversie, provenance, tijd, epistemische status en bewijsbeperkingen.'),('Meerdere bronnen','Dezelfde inhoud kan afzonderlijke beweringen met verschillende bronnen of gezagsgronden hebben.'),('Releasecontract','Verbind datasets, diensten, regels en beheerbesluiten aan een versiegebonden manifest.')])+'<p class="caption">Formele kern uit de paper: G = (N, L, E, τ, γ, κ); κ verbindt een geïdentificeerde edge met context.</p>',note='Het metamodel is een eigen ontwerpspecificatie. Onbekende context wordt expliciet zichtbaar. Een formele notatie betekent nog geen uitvoerbaar of gevalideerd profiel.')
add('11 / Tijd & epistemische status','Wat gold toen?<br>Wat wisten we toen?',cards([('Valid time','Het interval waarvoor een uitspraak volgens de bron geldt.'),('Registration time','Het interval waarin de uitspraak bij de gekozen registratie bekend was.'),('Epistemische dimensies','Uitspraaksoort, registratiehandeling, productiemethode, onzekerheid, gezagsgrond en bewijsstatus.')])+'<div class="callout">Normatief gedefinieerd, gezaghebbend geregistreerd en AI-afgeleid zijn verschillende kwalificaties. Een afleiding krijgt niet automatisch het gezag van haar bron.</div>','L14 S33 S37 S25',note='De samengestelde epistemische classificatie is een voorstel. Niet-authentiek, onbekend en onjuist zijn niet hetzelfde. AI-uitvoer heeft niet automatisch een gekalibreerde waarschijnlijkheid.')
add('12 / Design principles','Negen kandidaatprincipes.',table(['Betekenis & bewijs','Beheer & proportionaliteit'],[['DP1 · Onderscheid rollen en documenteer mappings.','DP6 · Publiceer een doel- en versiegebonden contract.'],['DP2 · Bind gezagsclaims aan uitspraken en bronnen.','DP7 · Beheer wijzigingen, terugmeldingen en besluiten.'],['DP3 · Onderscheid entiteit, record, versie en document.','DP8 · Motiveer ontologische verdieping én kosten.'],['DP4 · Scheid geldigheid van registratiekennis.','DP9 · Maak epistemische dimensies afzonderlijk zichtbaar.'],['DP5 · Scheid inferentie, validatie en feitelijke kwaliteit.','Alle principes: afgeleid, nog niet empirisch gevalideerd.']]),note='De volledige bronpassages, extra aannames en alternatieven staan in derivation-register.csv. Deze principes mogen niet als door het prototype bewezen best practices worden overgedragen.')
add('13 / Casus basisregistraties','Van BAG-fragment<br>naar een toetsbare keten.','<p class="lead">Huidige objectselectie: nummeraanduiding, verblijfsobject en pand. Relaties en uitbreiding naar andere registraties moeten nog brongecontroleerd worden uitgewerkt.</p>'+cards([('1 · Afbakenen','Een concrete gebruikstaak kiezen; tweede registratie en selectie onderbouwen.'),('2 · Onderbouwen','Definities, bronversies, identifiers, tijdvelden, gezagsgronden en mappings vastleggen.'),('3 · Onafhankelijk beoordelen','Verwachte antwoorden en negatieve gevallen door domeindeskundigen laten beoordelen.')])+'<p class="caption">Minimaal twee onafhankelijk beheerde registraties vóór een meerregistratieclaim: eigen onderzoeksvoorwaarde, geen bewijs van Stelselbrede representativiteit.</p>','S49',note='De genoemde BAG-categorieën zijn een objectselectie, geen empirische casustoets. Een volledige persoon–perceel–WOZ-keten is nog niet verantwoord. Synthetische records kunnen later dienen voor gecontroleerde scenario’s.')
add('14 / Overdracht aan productteam','Maak het prototype<br>vergelijkbaar met het voorstel.',table(['Op te leveren inventarisatie','Doel'],[['Repository, commit/release en configuratie','Een reproduceerbaar onderzoeksartefact identificeren.'],['Datasetselectie, bron- en modelversies','Vastleggen wat de implementatie daadwerkelijk gebruikt.'],['Mapping naar C1–C15 en R01–R23','Per onderdeel: aanwezig, gedeeltelijk, afwezig of niet beoordeeld.'],['Bewijs per eigenschap','Code-/configuratieverwijzing, model of documentatie; later apart een testuitkomst.'],['Beperkingen en wijzigingslog','Formatieve aanpassingen onderscheiden van de bevroren summatieve versie.']])+'<p class="callout">Huidige status van prototype-eigenschappen: niet beoordeeld. Ontbrekende documentatie bewijst geen ontbrekende functie.</p>',note='Dit is een overdrachtschecklist, geen implementatiebeoordeling. Er wordt geen technologie of productfunctie verondersteld.')
add('15 / Vergelijkend experiment','Geef beide oplossingen<br>dezelfde informatie.',cards([('A0 · Technisch','Masterdata met beperkte semantische context. Referentieconditie.'),('A1 · Conventioneel','Dezelfde broninhoud en historie in een conventioneel contextregister.'),('B1 · Expliciet verbonden','Dezelfde inhoud met getypeerde contextbindingen en afhankelijkheden.')])+'<div class="callout">Primaire vergelijking: B1 − A1 op correcte én herleidbare antwoorden, fouten en beheerlast.</div><p class="caption">Gelijke inhoud, toegang, training en antwoordbudget. Als contract en operaties gelijk zijn, resteert een implementatievergelijking.</p>',note='A0 tegenover B1 alleen zou extra informatie met het effect van representatie kunnen verwarren. De interventie moet vooraf aantoonbaar verschillen zonder B1 een informatievoorsprong te geven.')
add('16 / Voorgestelde evaluatie','Meet gedrag.<br>Tel niet alleen metadata.',table(['Experiment','Variatie','Te meten uitkomst'],[['E1 · Interpretatie','A0 / A1 / B1','Correcte én onderbouwde antwoorden; tijd en kosten.'],['E2 · Epistemische status','Annotatievorm × betrouwbaar / ontbrekend / misleidend','Onterechte gezagsopwaardering; passende en onnodige onthouding.'],['E3 · Ontologische verdieping','Modelreview zonder / met gerichte verdieping','Juist gevonden fouten, fout-positieven en analistentijd.'],['E4 · Historie & wijziging','Versiearchief zonder / met afhankelijkheden; resolutiestoringen','Historische correctheid, impactdetectie en hersteltijd.']])+'<p class="caption">Alle experimenten zijn gepland. Menselijke en AI-consumptie worden afzonderlijk beoordeeld.</p>',note='Voor AI worden model-, prompt- en retrievalversies vastgelegd. Meer metadata is op zichzelf geen bewijs voor betere interpretatie. Fouten verdwijnen niet achteraf uit de noemer.')
with (ROOT/'traceability-matrix.csv').open(encoding='utf-8-sig') as f: tr=list(csv.DictReader(f))
rows=[]
for rid in ['R01','R03','R04']:
 r=next(r for r in tr if r['requirement']==rid)
 rows.append([r['research_question'],r['literature_and_standards'],r['requirement']+' → '+r['design_principle'],r['architecture_component'],r['proposed_evaluation_metric']+' · '+r['metric_name']])
add('17 / Traceability','Elke ontwerpkeuze<br>krijgt een toetsroute.',table(['Vraag','Bronnen','Eis → principe','Component','Voorgestelde metriek'],rows)+'<p class="lead small">De volledige keten omvat 23 requirements. Een geldige verwijzingsketen onderbouwt de rationale; zij bewijst geen effectiviteit.</p>', 'S11 S13 S31 S08 S28 S38 S39 L08',note='Deze voorbeelden zijn rechtstreeks uit traceability-matrix.csv overgenomen. De aanvullende afleidingsregistratie legt aannames, alternatieven en tegenbewijs vast.')
add('18 / Beslisregels','Ook een eenvoudiger oplossing<br>mag winnen.',cards([('Ondersteuning','Een voldoende precies voordeel boven de vooraf gekozen relevante winst, binnen fout- en kostengrenzen.'),('Tegenbewijs','Geen praktisch relevante winst met voldoende precisie; of dezelfde kwaliteit tegen hogere kosten.'),('Onbeslist','Onzekerheidsintervallen zijn te breed om relevante winst te ondersteunen of tegen te spreken.')])+'<p class="callout">Marges, steekproef en analyse worden vóór de summatieve meting vastgelegd. Secundaire AI-winst redt geen gefaalde primaire hypothese.</p>',note='De grenzen voor relevante winst, kritieke fouten en extra beheerlast zijn nog niet vastgesteld. De these mag niet achteraf worden aangepast om negatieve uitkomsten te ontwijken.')
add('19 / Onderzoeksstatus','Wat geven we nu mee?',cards([('Wel beschikbaar','Een brongebonden ontwerpvoorstel, begripsgrenzen, architectuur, kandidaatprincipes en evaluatieprotocol.'),('Nog te leveren','Casusdossier, concrete profielen, prototype-inventarisatie, onafhankelijke antwoordenset en definitieve experimentopzet.'),('Nog te besluiten','Welke semantische functies noodzakelijk zijn en of hun baten de extra inspanning rechtvaardigen.')])+'<p class="lead small">Eerst de casus en beoordelingsmaatstaf vastleggen. Daarna het prototype ertegen evalueren.</p>',note='Volledige toepasselijke normteksten en externe review blijven nodig. De eerdere kritische manuscriptreview is door dezelfde AI-assistent uitgevoerd en is geen organisatorisch onafhankelijke peer review.')
# All source metadata is embedded, so handing over the HTML alone preserves the evidence index.
used=set()
import re
for slide in slides: used.update(re.findall(r'href="#source-([SL]\d+)"',slide))
items=[]
for sid in sorted(used):
 title,url,lim,version=sources[sid]
 items.append(f'<article id="source-{sid}"><strong>{sid} · {esc(title)}</strong><a href="{esc(url,quote=True)}" target="_blank" rel="noopener noreferrer">{esc(url)}</a><small>Versie / jaar: {esc(version)} · Bewijs: {esc(lim)}</small></article>')
add('Bijlage / Bronnen','Bronnen & bewijsgrenzen','<p class="caption">Overgenomen uit de repository; peildatum dossier: 7 september 2026. Geen nieuwe bronverificatie voor deze presentatie. Links openen externe bronnen; de presentatie zelf werkt offline.</p><div class="sources">'+''.join(items)+'</div>',note='S-ID’s verwijzen naar standards-matrix.csv, L-ID’s naar literature-matrix.csv. ISO/NEN-catalogusinformatie is geen volledige normlezing. Voor volledige claims en afleidingen: claims-register.csv en derivation-register.csv.',kind='source-slide')
css='''
:root{--bg:#101c29;--panel:#172a3b;--ink:#f4f4ee;--muted:#b9c7d0;--accent:#8ce2ce;--line:#344858}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Arial,Helvetica,sans-serif}button,a{touch-action:manipulation}a{color:var(--accent)}button{font:inherit;color:var(--ink);background:#203548;border:1px solid #466074;border-radius:7px;padding:8px 13px;cursor:pointer}button:hover{background:#355266}button:disabled{opacity:.35;cursor:default}button:focus-visible,a:focus-visible{outline:3px solid var(--accent);outline-offset:4px}.topbar{height:54px;padding:0 4vw;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid var(--line);font-size:12px;letter-spacing:1px}.badge{color:var(--accent)}.slide{display:none;max-width:1500px;margin:auto;min-height:calc(100vh - 116px);padding:32px 5vw 24px}.slide.active{display:block}.eyebrow{font-size:12px;letter-spacing:2px;text-transform:uppercase;color:var(--accent);margin-bottom:18px}h2{font-size:clamp(32px,3.65vw,60px);line-height:1.06;letter-spacing:-1.9px;margin:0 0 24px;max-width:1160px}p{line-height:1.5}.lead{font-size:clamp(19px,1.8vw,28px);max-width:1070px;color:var(--muted);margin:0 0 24px}.lead.small{font-size:21px;margin-top:25px}.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}.cards article{border-top:2px solid var(--accent);background:var(--panel);padding:21px;border-radius:0 0 8px 8px}.cards h3{font-size:19px;margin:0 0 12px}.cards p{font-size:17px;color:var(--muted);margin:0}.callout{border-left:3px solid var(--accent);padding:14px 20px;background:#193a40;margin-top:24px;font-size:19px;line-height:1.4}.caption{font-size:14px;color:var(--muted);line-height:1.5;margin-top:18px}table{border-collapse:collapse;width:100%;font-size:17px;line-height:1.35}th{text-align:left;color:var(--accent);font-size:12px;letter-spacing:1px;text-transform:uppercase}td,th{padding:13px 15px;border-bottom:1px solid var(--line);vertical-align:top}td:first-child{font-weight:600}tbody tr:nth-child(odd){background:var(--panel)}.table-wrap{overflow-x:auto}footer{font-size:11px;color:var(--muted);line-height:1.6;margin-top:24px}footer a{text-decoration:none}nav{position:sticky;bottom:0;background:#101c29f5;border-top:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;padding:10px 4vw;gap:10px;z-index:5}.controls{display:flex;gap:7px;align-items:center}.counter{font-size:13px;color:var(--muted);min-width:65px;text-align:center}.progress{position:fixed;bottom:0;left:0;height:3px;background:var(--accent);z-index:10}.notes{display:none;background:#f5e7c3;color:#17232b;padding:20px;margin-top:20px;border-radius:6px;line-height:1.5}.show-notes .active .notes{display:block}.notes p{margin-bottom:0}.flow{display:flex;align-items:center;justify-content:space-between;gap:12px;margin:30px 0}.flow div{flex:1;border:1px solid #547a80;padding:25px 15px;text-align:center;border-radius:8px;font-size:20px}.flow b{color:var(--accent)}.compact{margin:20px 0}.compact div{padding:15px}.formula{font-size:26px;color:var(--accent);padding:17px 0}.architecture{display:grid;grid-template-columns:4fr 1fr;gap:18px}.stack{display:grid;gap:9px}.stack>div{background:var(--panel);padding:17px 20px;border-left:3px solid var(--accent);display:flex;gap:20px;align-items:center}.stack small{color:var(--accent);min-width:62px}.stack strong{font-size:18px}.rail{border:1px solid #517277;border-radius:8px;padding:20px;color:var(--accent);line-height:1.4;font-size:16px}.rail hr{border:0;border-top:1px solid var(--line);margin:20px 0}.cover{padding-top:7vh;background:radial-gradient(ellipse at 95% 35%,#235551 0,transparent 50%)}.cover h2{font-size:clamp(48px,6vw,90px);max-width:1050px;margin-bottom:30px}.title-line{font-size:17px;margin:35px 0;color:var(--muted)}.stamp{display:inline-block;border:1px solid var(--accent);border-radius:20px;padding:10px 18px;color:var(--accent);font-size:13px}.sources{display:grid;grid-template-columns:1fr 1fr;gap:12px}.sources article{padding:13px;background:var(--panel);scroll-margin-top:25px}.sources a,.sources small{display:block;font-size:12px;overflow-wrap:anywhere;margin-top:8px}.sources small{color:var(--muted)}.source-slide h2{font-size:40px}.overview .slide{display:block;border-bottom:2px solid var(--line);min-height:auto;padding-top:45px;padding-bottom:45px}.overview nav{position:fixed;width:100%}.overview{padding-bottom:70px}.overview .notes{display:none}.keyhint{color:var(--muted);font-size:12px}.sr-only{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}
@media(max-width:760px){.slide{padding:25px 6vw;min-height:calc(100vh - 160px)}h2{letter-spacing:-1px}.cards,.sources{grid-template-columns:1fr}.architecture{grid-template-columns:1fr}.rail{font-size:14px}.stack>div{align-items:flex-start}.flow{flex-wrap:wrap}.flow div{min-width:105px}.keyhint{display:none}.topbar{font-size:10px;letter-spacing:0}nav{flex-wrap:wrap}.controls{gap:4px}button{padding:8px 10px;font-size:12px}td,th{padding:10px;font-size:14px}.cover{padding-top:8vh}.formula{font-size:20px}}
@media print{@page{size:A4 landscape;margin:10mm}*{-webkit-print-color-adjust:exact;print-color-adjust:exact}body{background:white;color:#142532;padding:0}.topbar,nav,.progress,.notes,.sr-only{display:none!important}.slide,.overview .slide{display:block!important;break-after:page;page-break-after:always;min-height:0;padding:0;border:0;max-width:none}.slide:last-child{break-after:auto}.eyebrow{font-size:9px;margin-bottom:10px;color:#175e58}h2{font-size:30px;line-height:1.06;margin-bottom:18px}.cover h2{font-size:60px}.cover{background:none;padding-top:20mm}.lead{font-size:18px;margin-bottom:15px}.lead.small{font-size:16px}.cards{gap:10px}.cards article,tbody tr:nth-child(odd),.stack>div,.sources article{background:#edf3f3}.cards article{padding:14px}.cards h3{font-size:15px}.cards p{font-size:13px;color:#344854}table{font-size:12px}td,th{padding:9px 10px;border-color:#cad6d9}th,.eyebrow,a,.flow b,.stack small,.rail{color:#175e58}.callout{font-size:15px;padding:10px 15px;background:#e6f3ef;margin-top:15px}.caption,footer{font-size:10px;color:#344854}.lead,.title-line{color:#344854}.flow{margin:20px 0}.flow div{padding:16px;font-size:16px}.stack>div{padding:12px}.stack strong{font-size:15px}.rail{font-size:14px}.formula{font-size:21px;color:#175e58}.stamp{color:#175e58}.source-slide{break-after:auto}.sources article{break-inside:avoid}.sources strong{font-size:11px}.sources a,.sources small{font-size:9px;color:#344854}.source-slide h2{font-size:28px}}
'''
js='''
const slides=[...document.querySelectorAll('.slide')];let current=0;
const prev=document.querySelector('#prev'),next=document.querySelector('#next'),counter=document.querySelector('#counter');
function show(n,hash=true){current=Math.max(0,Math.min(slides.length-1,n));slides.forEach((s,i)=>{s.classList.toggle('active',i===current);s.setAttribute('aria-current',i===current?'step':'false')});prev.disabled=current===0;next.disabled=current===slides.length-1;counter.textContent=`${current+1} / ${slides.length}`;document.querySelector('.progress').style.width=`${(current+1)/slides.length*100}%`;document.querySelector('#announce').textContent=`Dia ${current+1}: ${slides[current].querySelector('h2').textContent}`;if(hash)history.replaceState(null,'',`#dia-${current+1}`);if(document.body.classList.contains('overview'))slides[current].scrollIntoView();else window.scrollTo(0,0)}
function fromHash(){const m=location.hash.match(/^#dia-(\\d+)$/);if(m)show(Number(m[1])-1,false);else if(location.hash.startsWith('#source-')){show(slides.length-1,false);document.getElementById(location.hash.slice(1))?.scrollIntoView({block:'center'})}else show(0,false)}
prev.onclick=()=>show(current-1);next.onclick=()=>show(current+1);
function toggle(cls,id){const enabled=document.body.classList.toggle(cls);document.getElementById(id).setAttribute('aria-pressed',String(enabled));if(cls==='overview')show(current)}
document.querySelector('#notes').onclick=()=>toggle('show-notes','notes');document.querySelector('#overview').onclick=()=>toggle('overview','overview');document.querySelector('#print').onclick=()=>window.print();
document.querySelector('#full').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen()}catch(e){document.querySelector('#announce').textContent='Volledig scherm is niet beschikbaar in deze browser.'}};
document.addEventListener('keydown',e=>{if(e.ctrlKey||e.metaKey||e.altKey||/INPUT|TEXTAREA|SELECT|BUTTON|A/.test(e.target.tagName))return;if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();show(current+1)}else if(['ArrowLeft','PageUp'].includes(e.key)){e.preventDefault();show(current-1)}else if(e.key==='Home'){e.preventDefault();show(0)}else if(e.key==='End'){e.preventDefault();show(slides.length-1)}else if(e.key.toLowerCase()==='n')toggle('show-notes','notes');else if(e.key.toLowerCase()==='o')toggle('overview','overview')});
window.addEventListener('hashchange',fromHash);fromHash();
'''
out='<!DOCTYPE html>\n<html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="Onderzoekspresentatie bij het MDM-prototype: Semantic Master Data Product, voorgestelde architectuur en toekomstige evaluatie."><title>Semantic Master Data Product — onderzoek bij het prototype</title><style>'+css+'</style></head><body><header class="topbar"><span>SMDP / ONDERZOEK BIJ HET PROTOTYPE</span><span class="badge">VOORSTEL · NIET FORMEEL GEËVALUEERD</span></header><main>'+''.join(slides)+'</main><nav aria-label="Presentatiebediening"><div class="controls"><button id="prev" aria-label="Vorige dia">←</button><span id="counter" class="counter"></span><button id="next" aria-label="Volgende dia">→</button></div><span class="keyhint">← → dia’s · N notities · O overzicht</span><div class="controls"><button id="notes" aria-pressed="false">Notities</button><button id="overview" aria-pressed="false">Overzicht</button><button id="full">Volledig scherm</button><button id="print">Print / PDF</button></div></nav><div class="progress"></div><div id="announce" class="sr-only" aria-live="polite"></div><noscript><style>.slide{display:block}nav{display:none}</style><p>JavaScript is uitgeschakeld; alle dia’s worden onder elkaar getoond.</p></noscript><script>'+js+'</script></body></html>'
(ROOT/'presentation'/'semantic-master-data-product.html').write_text(out,encoding='utf-8')
print(f'Built {len(slides)} slides with {len(used)} embedded source entries.')
